    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.clusterSignalEClass, source, new String[]{"documentation", "A cluster signal represents the system signal on one specific communication cluster. "});
        this.addAnnotation((ENamedElement)this.getClusterSignal_Receivers(), source, new String[]{"documentation", "The receivers of the cluster signal. All transmitters and receivers of a cluster signal must be located on the same communication cluster."});
        this.addAnnotation((ENamedElement)this.getClusterSignal_SignalPosition(), source, new String[]{"documentation", "Reference to the signal position. The system signal at this position is represented on the communication cluster by the referencing cluster signal."});
        this.addAnnotation((ENamedElement)this.getClusterSignal_Transmitter(), source, new String[]{"documentation", "The transmitters of the cluster signal. All transmitters and receivers of a cluster signal must be located on the same communication cluster."});
        this.addAnnotation((ENamedElement)this.getClusterSignal_UpdateIndicationBitPosition(), source, new String[]{"documentation", "The UpdateIndicationBit indicates to the receivers that the clusterSignal was updated by the sender. Length is always one bit. The UpdateIndicationBitPosition attribute describes the position of the update bit within the PDU. "});
        this.addAnnotation((ENamedElement)this.clusterSignalTransmitterEClass, source, new String[]{"documentation", "A transmitter of the cluster signal. Since different transmitters can have different communication attribute values, a separate class is used per transmitter."});
        this.addAnnotation((ENamedElement)this.getClusterSignalTransmitter_CommunicationPort(), source, new String[]{"documentation", "Reference to the transmitting communication port."});
        this.addAnnotation((ENamedElement)this.clusterSignalReceiverEClass, source, new String[]{"documentation", "A receiver of the cluster signal. Since different receivers can have different communication attribute values, a separate class is used per receiver."});
        this.addAnnotation((ENamedElement)this.getClusterSignalReceiver_Timeout(), source, new String[]{"documentation", "Timeout in seconds. If the timeout occurs without  receiving the signal, the ECU shall take appropriate actions."});
        this.addAnnotation((ENamedElement)this.systemSignalGroupEClass, source, new String[]{"documentation", "A signal group refers to a set of signals that must always be kept together. A signal group is used to guarantee the atomic transfer of AUTOSAR composite data types.\r\n\r\n  "});
        this.addAnnotation((ENamedElement)this.getSystemSignalGroup_ContainedSignals(), source, new String[]{"documentation", "Reference to a set of signals that must always be kept together."});
        this.addAnnotation((ENamedElement)this.systemSignalEClass, source, new String[]{"documentation", "The system signal represents the communication system's view of data exchanged between SW components which reside on different ECUs. The system signals allow to represent this communication in a flattened structure, with (at least) one system signal defined for each data element sent or received by a SW component instance. If data has to be sent over gateways, there is still only one system signal representing this data. The representation of the data on the individual communication systems is done by the cluster signals.\r\n \r\nSystem signals can be defined independently of frames and PDUs. This allows a development methodology where the signals are defined first, and are assigned to frames in a later stage. \r\n\r\nAccording to the COM Specification, signal groups without signals are allowed. These have a \"signalLength\" = 0. In this case there shall be an \"update-bit\" configured. "});
        this.addAnnotation((ENamedElement)this.getSystemSignal_NeedsUpdateIndication(), source, new String[]{"documentation", "Boolean value that defines whether a UpdateIndicationBit has to be defined in the PDU that is associated with this SystemSignal. If this attribute is omitted, no UpdateIndication bit will be added to the PDU."});
        this.addAnnotation((ENamedElement)this.getSystemSignal_SignalLength(), source, new String[]{"documentation", "The signalLength specifies the size of the signal in bits. "});
        this.addAnnotation((ENamedElement)this.getSystemSignal_SignalTimingRequirements(), source, new String[]{"documentation", "A SystemSignal can have aggregated timing requirements. These timing requirements have to be taken into account when several cluster signals are grouped together into a frame."});
    }

